using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;
class AuditX3Contracts{static int Main(string[] a){try{if(a.Length!=4)throw new ArgumentException("editor source prepared output-json");string ed=Path.GetFullPath(a[0]);var domain=AppDomain.CreateDomain("X3ContractAudit",null,new AppDomainSetup{ApplicationBase=Path.GetDirectoryName(ed)});try{var w=(VerifiedNativeSquadsWorker)domain.CreateInstanceFromAndUnwrap(Assembly.GetExecutingAssembly().Location,typeof(VerifiedNativeSquadsWorker).FullName);w.AuditX3Contracts(Path.GetFullPath(a[1]),Path.GetFullPath(a[2]),Path.GetFullPath(a[3]));}finally{AppDomain.Unload(domain);}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
public sealed partial class VerifiedNativeSquadsWorker{
 static byte[] X3Slice(byte[] b,int start,int count){var result=new byte[count];Buffer.BlockCopy(b,start,result,0,count);return result;}
 public void AuditX3Contracts(string source,string prepared,string output){
  if(File.Exists(output))throw new IOException("Preserve existing contract audit; choose a new output path");
  var m=N4Read(Path.Combine(prepared,"manifest.json"));B7Pins(source,m);byte[] people=Load(source,"people_db.dat"),server=Load(source,"server_db.dat");var clubs=(Dictionary<int,string>)Call("ParseClubs",server);var nations=(Dictionary<int,string>)Call("ParseNations",server);var players=ReadPlayers(people,server,clubs,nations);var reused=new HashSet<int>(B7Rows(Path.Combine(prepared,"native_players.csv")).Select(x=>N4I(x,"ExistingID")).Where(x=>x>0));var wanted=new HashSet<int>(B7Rows(Path.Combine(prepared,"club_map.csv")).Select(x=>N4I(x,"TeamIndex")));var preserve=B7Ints(m,"preserve_absent_uids");var duplicates=B7Ints(m,"duplicate_retire_uids");var candidates=players.Where(x=>reused.Contains(x.Id)||duplicates.Contains(x.Id)||(wanted.Contains(x.ClubId)&&!preserve.Contains(x.Id))).ToList();var bad=new List<object>();int ok=0;
  foreach(var p in candidates){try{N4Evidence(people,p);ok++;}catch(Exception e){int st=p.PersonOffset-15,en=PersonEnd(people,p),owner=p.ClubIdOffset>0?p.ClubIdOffset:p.NationIdOffset+21;int length=(int)Call("GetNativeContractLength",people,owner+28,en-8,BitConverter.ToInt32(people,st));bad.Add(new{uid=p.Id,first=p.FirstName,last=p.LastName,dob=p.BirthDate,club=p.ClubId,reuse=reused.Contains(p.Id),duplicate=duplicates.Contains(p.Id),start=st,end=en,owner,nation=p.NationIdOffset,contract_length=length,reason=e.Message,record=Convert.ToBase64String(X3Slice(people,st,en-st))});}}
  B7Pins(source,m);N4Save(output,new{status=bad.Count==0?"pass":"blocked_actors_identified",source,checked_candidates=candidates.Count,supported=ok,problems=bad});Console.WriteLine("CONTRACT AUDIT checked="+candidates.Count+" supported="+ok+" blocked="+bad.Count);
 }
}
